// Adapted from shadcn/ui (MIT). ROC keeps one inline sidebar across widths.
"use client";
import * as React from "react";
import { Slot } from "./primitive-slot";
import { PanelLeft } from "lucide-react";
import { Button } from "./button";
import { Input } from "./input";
import { cn } from "./utils";
import "./sidebar.css";
type SidebarState = {
  open: boolean;
  setOpen: (open: boolean) => void;
  toggleSidebar: () => void;
};
const Context = React.createContext<SidebarState | null>(null);
export function useSidebar() {
  const value = React.useContext(Context);
  if (!value) throw new Error("Sidebar requires SidebarProvider");
  return value;
}
export function SidebarProvider({
  open: controlled,
  defaultOpen = true,
  onOpenChange,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (value: boolean) => void;
}) {
  const [local, setLocal] = React.useState(defaultOpen);
  const open = controlled ?? local;
  const setOpen = (value: boolean) => {
    if (controlled === undefined) setLocal(value);
    onOpenChange?.(value);
  };
  return (
    <Context.Provider
      value={{ open, setOpen, toggleSidebar: () => setOpen(!open) }}
    >
      <div
        className={cn("roc-ui roc-sidebar-host", className)}
        data-state={open ? "expanded" : "collapsed"}
        {...props}
      >
        {children}
      </div>
    </Context.Provider>
  );
}
export function Sidebar({
  className,
  children,
  ...props
}: React.ComponentProps<"aside">) {
  const { open } = useSidebar();
  return (
    <aside
      {...props}
      className={cn("roc-sidebar", className)}
      aria-hidden={!open}
      inert={!open}
    >
      <div className="roc-sidebar-inner">{children}</div>
    </aside>
  );
}
export function SidebarTrigger({
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar, open } = useSidebar();
  return (
    <Button
      variant="ghost"
      size="icon"
      aria-label="Toggle sidebar"
      aria-expanded={open}
      {...props}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) toggleSidebar();
      }}
    >
      <PanelLeft />
    </Button>
  );
}
export function SidebarInset({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div className={cn("roc-sidebar-inset", className)} {...props} />;
}
export function SidebarHeader({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div className={cn("roc-sidebar-header", className)} {...props} />;
}
export const SidebarFooter = SidebarHeader;
export function SidebarContent({
  className,
  ...props
}: React.ComponentProps<"nav">) {
  return <nav className={cn("roc-sidebar-content", className)} {...props} />;
}
export function SidebarGroup({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div className={cn("roc-sidebar-group", className)} {...props} />;
}
export function SidebarGroupLabel({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return <div className={cn("roc-sidebar-label", className)} {...props} />;
}
export function SidebarMenu({
  className,
  ...props
}: React.ComponentProps<"ul">) {
  return <ul className={cn("roc-sidebar-menu", className)} {...props} />;
}
export function SidebarMenuItem(props: React.ComponentProps<"li">) {
  return <li {...props} />;
}
export function SidebarMenuButton({
  asChild = false,
  isActive = false,
  className,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean; isActive?: boolean }) {
  const Comp = asChild ? Slot.Root : "button";
  return (
    <Comp
      type={asChild ? undefined : "button"}
      aria-current={isActive ? "page" : undefined}
      className={cn("roc-sidebar-link", className)}
      {...props}
    />
  );
}
export const SidebarInput = Input;

"use client";
// ROC primitive: render the caller's single child with our props merged in (`asChild`).
import * as React from "react";
import { composeRefs } from "./primitive-utils";

type AnyProps = Record<string, any>;

function mergeProps(slotProps: AnyProps, childProps: AnyProps) {
  const merged: AnyProps = { ...childProps };
  for (const key in childProps) {
    const slotValue = slotProps[key];
    const childValue = childProps[key];
    if (/^on[A-Z]/.test(key)) {
      if (slotValue && childValue) {
        merged[key] = (...args: unknown[]) => {
          const result = childValue(...args);
          slotValue(...args);
          return result;
        };
      } else if (slotValue) merged[key] = slotValue;
    } else if (key === "style") {
      merged[key] = { ...slotValue, ...childValue };
    } else if (key === "className") {
      merged[key] = [slotValue, childValue].filter(Boolean).join(" ");
    }
  }
  return { ...slotProps, ...merged };
}

type SlotProps = React.HTMLAttributes<HTMLElement> & {
  children?: React.ReactNode;
  ref?: React.Ref<any>;
};

function Root({ children, ref, ...slotProps }: SlotProps) {
  if (!React.isValidElement(children)) {
    if (React.Children.count(children) > 1) throw new Error("Slot needs one child");
    return null;
  }
  const child = children as React.ReactElement<AnyProps>;
  return React.cloneElement(child, {
    ...mergeProps(slotProps, child.props),
    ref: ref ? composeRefs(ref, child.props.ref) : child.props.ref,
  });
}

export const Slot = { Root };

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Slot } from "./primitive-slot";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp = asChild ? Slot.Root : "button";

  return (
    <Comp
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 8px;
  min-height: 36px;
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-radius, 8px);
  font-weight: 500;
  line-height: 1.2;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-ink, #252525);
  color: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible {
  outline: 2px solid var(--roc-focus, #737373);
  outline-offset: 3px;
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cn } from "./utils";

function Input({ className, type, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      type={type}
      data-slot="input"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

export { Input };

import "./input.css";

@import "./ui-base.css";
.roc-ui[data-slot="input"] {
  display: block;
  min-width: 0;
  width: 100%;
  height: 38px;
  border: 1px solid var(--roc-line, #dcdcdc);
  border-radius: var(--roc-radius, 8px);
  padding: 8px 11px;
  background: var(--roc-paper, #fff);
  line-height: 1.5;
  transition: border-color var(--roc-motion-quick) ease-out;
}
.roc-ui[data-slot="input"]::placeholder {
  color: var(--roc-muted, #888);
}
.roc-ui[data-slot="input"][aria-invalid="true"] {
  border-color: #bd4545;
  animation: roc-ui-shake 240ms var(--roc-motion-ease);
}
.roc-ui[data-slot="input"]::file-selector-button {
  border: 0;
  background: transparent;
  margin-right: 10px;
  font: inherit;
}
@media (pointer: coarse) {
  .roc-ui[data-slot="input"] {
    font-size: 16px;
    min-height: 44px;
  }
}

@import "./ui-base.css";
.roc-sidebar-host {
  display: flex;
  min-width: 0;
  container-type: inline-size;
  position: relative;
  isolation: isolate;
  border: 1px solid var(--roc-line, #e5e5e5);
  border-radius: 10px;
  overflow: hidden;
}
.roc-sidebar {
  flex: none;
  width: var(--roc-sidebar-width, 180px);
  max-width: 65%;
  overflow: hidden;
  background: var(--roc-surface, #f7f7f7);
  transition:
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    visibility 220ms;
}
.roc-sidebar-host[data-state="collapsed"] > .roc-sidebar {
  width: 0;
  visibility: hidden;
}
.roc-sidebar-inner {
  width: var(--roc-sidebar-width, 180px);
  max-width: 100%;
  display: flex;
  flex-direction: column;
  height: 100%;
}
.roc-sidebar-header,
.roc-sidebar-content {
  padding: 12px;
}
.roc-sidebar-content {
  flex: 1;
  overflow: auto;
}
.roc-sidebar-label {
  font-size: 11px;
  color: #777;
  padding: 4px 8px 8px;
}
.roc-sidebar-menu {
  display: grid;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.roc-sidebar-link {
  font: inherit;
  border: 0;
  border-radius: 6px;
  background: transparent;
  text-decoration: none;
  color: inherit;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px;
  text-align: start;
  cursor: pointer;
}
.roc-sidebar-link:hover,
.roc-sidebar-link[aria-current="page"] {
  background: #eaeaea;
}
.roc-sidebar-link svg {
  width: 16px;
  height: 16px;
}
.roc-sidebar-inset {
  flex: 1;
  min-width: 0;
  padding: 10px;
  background: #fff;
}
@container (max-width:420px) {
  .roc-sidebar {
    --roc-sidebar-width: 140px;
  }
  .roc-sidebar-header,
  .roc-sidebar-content {
    padding: 8px;
  }
}
